def load_env_file(path: str = "/etc/wendui-engine-tool-api.env") -> None:
    if not os.path.exists(path):
        return
    try:
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                os.environ.setdefault(k.strip(), v.strip().strip('"').strip("'"))
    except Exception:
        pass


def refresh_config() -> tuple[str | None, str, str]:
    load_env_file()
    key = os.getenv("ARK_API_KEY") or os.getenv("DOUBAO_API_KEY") or os.getenv("VOLCENGINE_API_KEY")
    model = os.getenv("ARK_MODEL") or os.getenv("DOUBAO_MODEL") or ARK_MODEL
    endpoint = os.getenv("ARK_ENDPOINT") or ARK_ENDPOINT
    return key, model, endpoint


def send_json(handler: BaseHTTPRequestHandler, status: int, data: dict) -> None:
    body = json.dumps(data, ensure_ascii=False).encode("utf-8")
    handler.send_response(status)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Cache-Control", "no-store")
    handler.send_header("Access-Control-Allow-Origin", "*")
    handler.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
    handler.send_header("Access-Control-Allow-Headers", "Content-Type")
    handler.send_header("Content-Length", str(len(body)))
    handler.end_headers()
    handler.wfile.write(body)


def extract_json(text: str) -> dict | None:
    text = text.strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text)
        text = re.sub(r"\s*```$", "", text)
    try:
        return json.loads(text)
    except Exception:
        pass
    m = re.search(r"\{[\s\S]*\}", text)
    if m:
        try:
            return json.loads(m.group(0))
        except Exception:
            return None
    return None


def loose_sections_from_text(text: str) -> list[dict] | None:
    """Best-effort recovery when a model returns JSON-looking text with minor syntax damage."""
    if '"sections"' not in text or '"title"' not in text:
        return None
    out=[]
    for m in re.finditer(r'"title"\s*:\s*"((?:\\.|[^"\\])*)"\s*,\s*"items"\s*:\s*\[(.*?)\](?=\s*,\s*\{|\s*\]|\s*\})', text, re.S):
        title_raw=m.group(1); block=m.group(2)
        try:
            title=json.loads('"'+title_raw+'"')
        except Exception:
            title=title_raw
        items=[]
        for im in re.finditer(r'"((?:\\.|[^"\\])*)"', block, re.S):
            raw=im.group(1)
            try:
                val=json.loads('"'+raw+'"')
            except Exception:
                val=raw.replace('\\n','\n')
            if val.strip(): items.append(val.strip())
        if items:
            out.append({"title": str(title)[:80], "items": items[:8]})
    return out[:16] or None


def call_local_doubao_proxy(app_name: str, prompt: str) -> dict | None:
    """Call existing local Doubao proxy if available. Does not expose secrets."""
    payload = {
        "system": TOOL_SYSTEM,
        "prompt": prompt,
        "max_tokens": 1800,
        "temperature": 0.45,
    }
    req = urllib.request.Request(
        "http://127.0.0.1:8199/api/generate",
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=50) as resp:
            raw = resp.read().decode("utf-8", "replace")
            data = json.loads(raw)
    except Exception:
        return None
    if data.get("status") != "ok":
        return None
    content = data.get("content") or ""
    parsed = extract_json(content)
    if parsed and isinstance(parsed.get("sections"), list):
        return {"ok": True, "status": "model", "provider": "local-doubao-proxy", "model": data.get("model"), "data": polish_model_data(app_name, parsed, prompt)}
    loose = loose_sections_from_text(content)
    if loose:
        return {"ok": True, "status": "model", "provider": "local-doubao-proxy", "model": data.get("model"), "data": polish_model_data(app_name, {"sections": loose, "quality_note": "模型返回了类JSON文本，节点引擎已自动修复为结构化章节。"}, prompt)}
    return {"ok": True, "status": "model_text", "provider": "local-doubao-proxy", "model": data.get("model"), "data": {"sections": [{"title": "豆包生成结果", "items": [content]}], "quality_note": "本机豆包代理已返回文本结果。"}}


