def extract_history_scene(input_text: str) -> str:
    raw = str(input_text or '')
    m = re.search(r'历史情景或古诗词[：:]\s*([^。；;\n]{2,80})', raw)
    if m:
        return m.group(1).strip()
    m = re.search(r'主题[：:]\s*([^。；;\n]{2,60})', raw)
    return m.group(1).strip() if m else raw[:60].strip()


def history_result_matches_input(input_text: str, sections: list[dict]) -> bool:
    scene = extract_history_scene(input_text)
    text = json.dumps(sections or [], ensure_ascii=False)
    positive = [x for x in re.split(r'[：:，,、\s]+', scene) if len(x) >= 2][:8]
    if positive and not any(x in text for x in positive):
        return False
    contamination_groups = [
        ['赤壁','黄盖','周瑜','火攻','东南风'],
        ['商鞅','变法','奖励耕战','废井田'],
        ['秦统一','统一文字','统一货币','郡县制'],
        ['白毛','绿水','红掌','清波'],
    ]
    scene_has = lambda group: any(x in scene for x in group)
    for group in contamination_groups:
        if not scene_has(group) and sum(text.count(x) for x in group) >= 2:
            return False
    return True

def call_ark(app_name: str, user_input: str, scenario: str) -> dict:
    key, model, endpoint = refresh_config()
    rule = TOOL_RULES.get(app_name, "按教育工具应用要求输出结构化结果。")
    prompt = f"应用：{app_name}\n使用场景：{scenario}\n规则：{rule}\n用户输入：\n{user_input[:MAX_INPUT]}"
    if not key:
        local = call_local_doubao_proxy(app_name, prompt)
        if local:
            return local
        # Deterministic backend fallback for the reference Top10 tools.
        # This is explicit local generation, not pretending to be a model call.
        specific = build_ygbh_top10_specific_sections(app_name, user_input)
        if specific:
            return {"ok": True, "status": "deterministic_fallback", "provider": "node-engine-local-template", "model": None, "data": {"sections": specific, "quality_note": "服务端未配置模型密钥时，节点引擎使用月光宝盒Top10对标结构化模板生成，可保存为真实产品成果；未冒充模型调用。"}}
        # Existing hardened apps may also have deterministic builders.
        hardened = polish_model_data(app_name, {"sections": [{"title": "生成结果", "items": [user_input[:260] or app_name]}], "quality_note": "本地结构化兜底。"}, user_input)
        return {"ok": True, "status": "deterministic_fallback", "provider": "node-engine-local-template", "model": None, "data": hardened}
    payload = {
        "model": model,
        "messages": [
            {"role": "system", "content": TOOL_SYSTEM},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0.45,
        "max_tokens": 1800,
    }
    req = urllib.request.Request(
        endpoint,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {key}"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=45) as resp:
            raw = resp.read().decode("utf-8", "replace")
            data = json.loads(raw)
    except urllib.error.HTTPError as e:
        msg = e.read().decode("utf-8", "replace")[:600]
        if app_name == '历史情景插图':
            specific = build_ygbh_top10_specific_sections(app_name, user_input)
            if specific:
                return {"ok": True, "status": "text_model_fallback", "provider": "node-engine-local-structure", "model": None, "data": {"sections": specific, "quality_note": "文本模型暂时不可用，已使用本地结构化方案兜底；图片生成仍调用豆包真实图片模型。"}}
        return {"ok": False, "status": "provider_http_error", "message": f"模型接口HTTP错误：{e.code}", "detail": msg}
    except Exception as e:
        if app_name == '历史情景插图':
            specific = build_ygbh_top10_specific_sections(app_name, user_input)
            if specific:
                return {"ok": True, "status": "text_model_fallback", "provider": "node-engine-local-structure", "model": None, "data": {"sections": specific, "quality_note": "文本模型暂时不可用，已使用本地结构化方案兜底；图片生成仍调用豆包真实图片模型。"}}
        return {"ok": False, "status": "provider_error", "message": f"模型接口调用失败：{type(e).__name__}: {e}"}

    content = ""
    try:
        content = data["choices"][0]["message"]["content"]
    except Exception:
        return {"ok": False, "status": "provider_bad_response", "message": "模型响应结构异常。"}
    parsed = extract_json(content)
    if parsed and isinstance(parsed.get("sections"), list):
        polished = polish_model_data(app_name, parsed, prompt)
        if app_name == '历史情景插图' and not history_result_matches_input(user_input, polished.get('sections') or []):
            specific = build_ygbh_top10_specific_sections(app_name, user_input)
            polished = {"sections": specific or [], "quality_note": "模型结果与当前主题不一致，节点引擎已按当前输入重建结构化方案；图片生成仍调用豆包真实图片模型。"}
            return {"ok": True, "status": "theme_guard_fallback", "provider": "node-engine-local-structure", "model": None, "data": polished, "latency_ms": None}
        return {"ok": True, "status": "model", "provider": "doubao/ark", "model": model, "data": polished, "latency_ms": None}
    loose = loose_sections_from_text(content)
    if loose:
        polished = polish_model_data(app_name, {"sections": loose, "quality_note": "模型返回了类JSON文本，节点引擎已自动修复为结构化章节。"}, prompt)
        if app_name == '历史情景插图' and not history_result_matches_input(user_input, polished.get('sections') or []):
            specific = build_ygbh_top10_specific_sections(app_name, user_input)
            polished = {"sections": specific or [], "quality_note": "模型结果与当前主题不一致，节点引擎已按当前输入重建结构化方案；图片生成仍调用豆包真实图片模型。"}
            return {"ok": True, "status": "theme_guard_fallback", "provider": "node-engine-local-structure", "model": None, "data": polished}
        return {"ok": True, "status": "model", "provider": "doubao/ark", "model": model, "data": polished}
    return {"ok": True, "status": "model_text", "provider": "doubao/ark", "model": model, "data": {"sections": [{"title": "模型生成结果", "items": [content]}], "quality_note": "模型未返回标准JSON，已按文本结果展示。"}}


def ensure_generated_dir() -> None:
    GENERATED_DIR.mkdir(parents=True, exist_ok=True)


def safe_name(name: str) -> str:
    raw = str(name or "artifact")
    ascii_part = re.sub(r"[^0-9A-Za-z_-]+", "-", raw).strip("-").lower()
    if not ascii_part:
        if "PPT" in raw or "ppt" in raw.lower(): ascii_part = "ppt-tool"
        elif "思维导图" in raw: ascii_part = "mindmap-tool"
        elif "历史" in raw or "插图" in raw: ascii_part = "history-visual-tool"
        elif "素材" in raw or "链接" in raw: ascii_part = "material-tool"
        elif "听默写" in raw or "默写" in raw: ascii_part = "dictation-tool"
        elif "出题" in raw or "知识点" in raw: ascii_part = "quiz-tool"
        elif "作文" in raw or "批改" in raw: ascii_part = "writing-feedback-tool"
        elif "学历案" in raw: ascii_part = "learning-plan-tool"
        elif "大单元知识图谱" in raw: ascii_part = "unit-knowledge-map"
        elif "跨学科PBL" in raw: ascii_part = "pbl-design-tool"
        elif "教育案例分析" in raw: ascii_part = "case-analysis-tool"
        elif "大单元设计Plus" in raw: ascii_part = "unit-design-plus"
        elif "说课稿" in raw: ascii_part = "lesson-speech-tool"
        elif "教案" in raw: ascii_part = "lesson-plan-tool"
        else: ascii_part = "tool-app"
    return ascii_part[:48]


def new_artifact_id(app: str) -> str:
    return f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{safe_name(app)}-{uuid.uuid4().hex[:8]}"


def normalize_sections(payload: dict) -> list[dict]:
    sections = payload.get("sections") or payload.get("data", {}).get("sections") or []
    if isinstance(sections, list) and sections:
        out=[]
        for s in sections[:16]:
            title = str(s.get("title") if isinstance(s, dict) else "生成结果")[:80]
            items = s.get("items") if isinstance(s, dict) else [str(s)]
            if not isinstance(items, list):
                items=[str(items)]
            out.append({"title": title or "生成结果", "items": [str(x)[:900] for x in items[:8]]})
        return out
    text = re.sub(r"<[^>]+>", " ", str(payload.get("text") or payload.get("html") or payload.get("input") or "生成结果"))
    parts=[x.strip() for x in re.split(r"\n{2,}|(?=第[一二三四五六七八九十]+[、.])", text) if x.strip()]
    return [{"title":"生成结果","items":parts[:8] or [text[:900]]}]


def sections_to_plain(sections: list[dict]) -> str:
    chunks=[]
    for s in sections:
        chunks.append(str(s.get("title","生成结果")))
        for item in s.get("items",[]):
            chunks.append("- "+str(item))
    return "\n".join(chunks)


def safe_public_text(text: str) -> str:
    text=str(text or '')
    replacements={
        '绕过平台限制':'遵守平台规则',
        '绕过':'遵守规则',
        '二次搬运':'再发布',
        '搬运':'转载',
        '下载原视频':'记录素材来源',
        '提取视频':'记录素材来源',
        '无水印':'规范标注来源',
        '去水印':'规范标注来源',
        '破解':'合规使用',
        '规避版权':'遵守版权边界',
        '泛模板':'空泛表述',
        '重写整篇':'完成整篇',
    }
    for old,new in replacements.items():
        text=text.replace(old,new)
    text=re.sub(r'负面约束[:：][^。；;]*[。；;]?', '', text)
    text=re.sub(r'不要[^。；;]*[。；;]?', '', text)
    text=re.sub(r'不应[^。；;]*[。；;]?', '', text)
    text=re.sub(r'避免[^。；;]*[。；;]?', '', text)
    return text.strip()


def generated_records(limit: int = 80) -> list[dict]:
    ensure_generated_dir()
    rows=[]
    for jp in sorted(GENERATED_DIR.glob('*.json'), key=lambda x: x.stat().st_mtime, reverse=True)[:limit]:
        try:
            d=json.loads(jp.read_text(encoding='utf-8'))
            aid=d.get('id') or jp.stem
            rows.append({
                "id": aid,
                "app": d.get('app','官方工具应用'),
                "input": d.get('input',''),
                "created_at": d.get('created_at', jp.stat().st_mtime),
                "url": f"{PUBLIC_BASE}/{aid}.html",
                "json_url": f"{PUBLIC_BASE}/{aid}.json",
            })
        except Exception:
            continue
    return rows


def write_artifact_index() -> str:
    ensure_generated_dir()
    rows=generated_records(120)
    cards=[]
    for r in rows:
        ts=datetime.fromtimestamp(float(r.get('created_at') or time.time())).strftime('%Y-%m-%d %H:%M')
        cards.append(f"<article class='card'><div><span>{html.escape(ts)}</span><h2>{html.escape(str(r['app']))}</h2><p>{html.escape(safe_public_text(str(r.get('input','')))[:150])}</p></div><a href='{html.escape(r['url'])}' target='_blank'>打开成果</a></article>")
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>节点引擎官方工具成果库</title><style>body{{margin:0;background:#f6f8fb;color:#101828;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:42px 54px;background:linear-gradient(135deg,#172554,#3157d5);color:white}}.hero h1{{font-size:42px;margin:0 0 12px}}.hero p{{opacity:.86}}main{{max-width:1180px;margin:0 auto;padding:28px}}.card{{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;align-items:center;background:white;border:1px solid #e5e7eb;border-radius:24px;padding:22px 24px;margin:14px 0;box-shadow:0 14px 34px rgba(15,23,42,.06)}}.card span{{font-size:12px;color:#64748b;font-weight:800}}.card h2{{margin:6px 0 8px;color:#172554}}.card p{{margin:0;color:#475569;line-height:1.65}}.card a{{background:#3157d5;color:#fff;text-decoration:none;border-radius:14px;padding:11px 16px;font-weight:900;white-space:nowrap}}@media(max-width:640px){{.hero{{padding:30px 22px}}main{{padding:18px}}.card{{grid-template-columns:1fr}}}}
</style></head><body><header class='hero'><h1>节点引擎官方工具成果库</h1><p>这里收纳通过官方工具应用生成并保存的服务端产品成果，可用于复盘、复用和继续公开发布。</p></header><main>{''.join(cards) or '<p>暂无成果。</p>'}</main></body></html>"""
    path=GENERATED_DIR/'index.html'
    path.write_text(doc, encoding='utf-8')
    return f"{PUBLIC_BASE}/index.html"


