    ensure_generated_dir()
    aid=new_artifact_id(app)
    icons={'封面':'🎬','学习目标':'🎯','情境导入':'🌡️','安全提醒':'✅','认识元件':'🔋','点亮小灯泡':'💡','错误连接诊断':'🛠️','串联与并联':'🔀','分组实验记录':'🧪','数轴比较':'📏','正负数比较':'➕','两个负数比较':'↔️','例题讲解':'🧮','课堂练习':'✍️','课堂小结':'🧠','课后任务':'📌'}
