def write_convert_lesson_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    """Interactive closed-loop mini system for converting materials to lesson plans."""
    ensure_generated_dir()
    aid=new_artifact_id(app)
    def section(title):
        for s in sections:
            if str(s.get('title','')) == title:
                return [str(x) for x in s.get('items',[])]
        return []
    order=['保留信息','删改与补齐建议','教学目标','教学重难点','教学流程','学生活动','评价与作业','板书与资源准备']
    icons={'保留信息':'🧾','删改与补齐建议':'✂️','教学目标':'🎯','教学重难点':'⭐','教学流程':'🧭','学生活动':'🧪','评价与作业':'✅','板书与资源准备':'🧩'}
    cards=[]
    for idx,title in enumerate(order,1):
        items=section(title)
        lis=''.join(f"<li>{html.escape(safe_public_text(i))}</li>" for i in items) or '<li>待补充。</li>'
        wide=' wide' if title in ('教学流程','删改与补齐建议','保留信息') else ''
        cards.append(f"<section class='result-card{wide}' data-section='{html.escape(title)}'><div class='card-head'><span>{icons.get(title,'📌')}</span><div><em>{idx:02d}</em><h2>{html.escape(title)}</h2></div></div><ul>{lis}</ul></section>")
    initial_sections=json.dumps(sections, ensure_ascii=False)
    initial_input=json.dumps(input_text, ensure_ascii=False)
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 独立材料转教案小系统</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f0fdf4;color:#101828;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:44px 56px;background:radial-gradient(circle at 82% 16%,rgba(45,212,191,.30),transparent 28%),linear-gradient(135deg,#064e3b,#0f766e);color:#fff;position:relative;overflow:hidden}}.hero:after{{content:'';position:absolute;right:-90px;top:-90px;width:320px;height:320px;border-radius:50%;background:rgba(255,255,255,.13)}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.30);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:950;font-size:13px}}h1{{font-size:42px;margin:18px 0 10px;letter-spacing:-.04em}}.hero p{{max-width:980px;opacity:.93;line-height:1.75}}.hero-actions{{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}}.hero-actions a,.hero-actions button{{appearance:none;border:0;background:#fff;color:#0f766e;text-decoration:none;border-radius:16px;padding:12px 16px;font-weight:950;box-shadow:0 12px 26px rgba(15,23,42,.14);cursor:pointer}}main{{max-width:1340px;margin:0 auto;padding:28px}}.system-grid{{display:grid;grid-template-columns:minmax(380px,.82fr) minmax(0,1.18fr);gap:20px;align-items:start}}.panel{{background:#fff;border:1px solid #99f6e4;border-radius:28px;box-shadow:0 18px 44px rgba(6,78,59,.07)}}.form-panel{{position:sticky;top:18px;padding:22px}}.panel-title{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}}.panel-title h2{{margin:0;color:#0f766e;font-size:24px}}.badge{{display:inline-flex;align-items:center;border-radius:999px;background:#ccfbf1;color:#0f766e;padding:7px 10px;font-weight:950;font-size:12px}}label{{display:block;font-size:13px;color:#475569;font-weight:900;margin:14px 0 7px}}input,select,textarea{{width:100%;border:1px solid #99f6e4;background:#f7fffc;border-radius:16px;padding:12px 13px;font:inherit;color:#111827;outline:none}}textarea{{min-height:210px;resize:vertical;line-height:1.62}}input:focus,select:focus,textarea:focus{{border-color:#0f766e;box-shadow:0 0 0 4px rgba(15,118,110,.12)}}.field-row{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.btn-row{{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;margin-top:18px}}button.primary,button.secondary,button.ghost{{appearance:none;border:0;border-radius:16px;padding:13px 14px;font-weight:950;cursor:pointer}}button.primary{{background:#0f766e;color:#fff;box-shadow:0 14px 28px rgba(15,118,110,.24)}}button.secondary{{background:#3157d5;color:#fff}}button.ghost{{background:#ecfdf5;color:#0f766e}}button:disabled{{opacity:.58;cursor:not-allowed}}.tips{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}}.tips span{{background:#ecfdf5;color:#065f46;border-radius:14px;padding:10px;font-size:12px;font-weight:800;line-height:1.45}}.result-panel{{padding:0;overflow:hidden}}.result-head{{padding:22px 24px;border-bottom:1px solid #d1fae5;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:linear-gradient(180deg,#fff,#f7fffc)}}.result-head h2{{margin:0;color:#064e3b;font-size:25px}}.status{{font-size:13px;color:#64748b;font-weight:800}}.task{{margin:20px 24px;background:#fff;border:1px solid #99f6e4;border-radius:24px;padding:20px;box-shadow:0 12px 28px rgba(6,78,59,.045)}}.task h3{{margin:0 0 10px;color:#0f766e}}.task p{{line-height:1.75;color:#334155;white-space:pre-wrap}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;padding:0 24px 24px}}.result-card{{background:#fff;border:1px solid #99f6e4;border-radius:24px;padding:20px;box-shadow:0 14px 34px rgba(6,78,59,.055)}}.result-card.wide{{grid-column:span 2}}.card-head{{display:flex;gap:12px;align-items:center;margin-bottom:12px}}.card-head span{{display:grid;place-items:center;width:42px;height:42px;border-radius:16px;background:#ccfbf1;font-size:20px}}.card-head em{{font-style:normal;font-size:12px;color:#64748b;font-weight:950;letter-spacing:.08em}}.result-card h2{{margin:2px 0 0;color:#0f766e;font-size:22px}}li{{margin:10px 0;line-height:1.78;color:#334155}}.closed-loop{{margin:0 24px 24px;border-left:6px solid #0f766e;background:#ecfdf5;border-radius:22px;padding:18px;color:#065f46;line-height:1.72}}.toast{{position:fixed;right:20px;bottom:20px;background:#111827;color:#fff;border-radius:16px;padding:13px 16px;box-shadow:0 16px 40px rgba(15,23,42,.28);font-weight:900;opacity:0;transform:translateY(10px);transition:.2s;z-index:20}}.toast.show{{opacity:1;transform:translateY(0)}}.meta{{font-size:13px;color:#64748b;margin:0 24px 24px}}@media(max-width:980px){{.hero{{padding:32px 22px}}h1{{font-size:32px}}main{{padding:18px}}.system-grid{{grid-template-columns:1fr}}.form-panel{{position:static}}.grid{{grid-template-columns:1fr}}.result-card.wide{{grid-column:auto}}.tips{{grid-template-columns:1fr}}}}@media(max-width:560px){{.field-row,.btn-row{{grid-template-columns:1fr}}}}

</style></head><body><header class='hero'><div class='eyebrow'>一键转教案 · 独立材料转化小系统</div><h1>{html.escape(app)}</h1><p>把逐字稿、课件说明、课堂实录或零散备课材料转成规范教案。系统会保留可上课信息、清理口语废话、补齐目标/流程/评价/作业/板书，并支持保存与导出。</p><div class='hero-actions'><a href='{PUBLIC_BASE}/index.html' target='_blank'>打开成果库</a><button type='button' onclick='document.getElementById("sourceText").focus()'>粘贴材料开始转化</button></div></header><main><div class='system-grid'><aside class='panel form-panel'><div class='panel-title'><h2>转化参数</h2><span class='badge'>材料→教案闭环</span></div><div class='field-row'><div><label for='stage'>学段</label><select id='stage'><option>七年级</option><option>小学四年级</option><option>小学五年级</option><option>八年级</option><option>高一</option></select></div><div><label for='subject'>学科</label><select id='subject'><option>数学</option><option>语文</option><option>历史</option><option>科学</option><option>英语</option></select></div></div><div class='field-row'><div><label for='topic'>课题</label><input id='topic' value='数轴' placeholder='例如：数轴、秦统一中国'></div><div><label for='materialType'>材料类型</label><select id='materialType'><option>课堂逐字稿</option><option>课件说明</option><option>零散备课笔记</option><option>课堂实录</option></select></div></div><label for='strategy'>转化策略</label><select id='strategy'><option>保留关键教学信息，补齐完整教案</option><option>压缩口语，强化问题链和活动</option><option>转成公开课可展示教案</option><option>转成基础班可执行教案</option></select><label for='sourceText'>原始材料</label><textarea id='sourceText'>老师：今天我们用温度计和楼层图来认识数轴。先看0在哪里，向右表示正方向，向左表示负方向。学生回答：正数在右边，负数在左边。老师追问：如果每一格长度不一样，还能准确表示数吗？接着小组用纸带画数轴，标出-3、0、2、1.5，并比较大小。最后做当堂检测，在数轴上表示-1/2和3。</textarea><div class='btn-row'><button class='primary' id='generateBtn' type='button'>转成教案</button><button class='secondary' id='saveBtn' type='button'>保存成果</button></div><div class='btn-row'><button class='ghost' id='exportBtn' type='button'>导出文本</button><button class='ghost' id='resetBtn' type='button'>恢复示例</button></div><div class='tips'><span>保留：导入/追问/活动/练习</span><span>清理：口语冗余和跳跃表述</span><span>补齐：目标/评价/作业/板书</span></div></aside><section class='panel result-panel'><div class='result-head'><h2>当前转化成果</h2><div class='status' id='status'>已加载一份材料转教案成果，可继续重生成。</div></div><section class='task'><h3>原始材料任务</h3><p id='taskText'>{html.escape(safe_public_text(input_text))}</p></section><div class='grid' id='resultGrid'>{''.join(cards)}</div><section class='closed-loop'><b>业务闭环说明：</b>本应用已具备“粘贴材料 → 选择转化策略 → 一键转教案 → 保存到成果库 → 导出文本 → 修改材料再转化”的完整小系统流程。</section><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用 · artifact_id={html.escape(aid)}</div></section></div></main><div class='toast' id='toast'></div><script>
const API='/wendui-engine-api';
let currentSections={initial_sections};
let currentInput={initial_input};
const order={json.dumps(order, ensure_ascii=False)};
const icons={json.dumps(icons, ensure_ascii=False)};
function toast(msg){{const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}}
function esc(s){{return String(s||'').replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]))}}
function buildInput(){{const v=id=>document.getElementById(id).value.trim();return `请把以下${{v('stage')}}${{v('subject')}}《${{v('topic')}}》${{v('materialType')}}转成一份规范可上课教案。转化策略：${{v('strategy')}}。要求：保留导入问题、学生回答、教师追问、练习、核心术语等关键可上课信息；清理口语废话；补齐教学目标、重难点、教学流程、学生活动、评价与作业、板书与资源准备。原始材料：${{v('sourceText')}}`;}}
function render(sections){{currentSections=sections||[];const grid=document.getElementById('resultGrid');const map=new Map(currentSections.map(s=>[String(s.title||''),Array.isArray(s.items)?s.items:[]]));let html='';let i=1;for(const title of order){{const items=map.get(title)||[];const wide=(title==='教学流程'||title==='删改与补齐建议'||title==='保留信息')?' wide':'';html+=`<section class="result-card${{wide}}"><div class="card-head"><span>${{icons[title]||'📌'}}</span><div><em>${{String(i).padStart(2,'0')}}</em><h2>${{esc(title)}}</h2></div></div><ul>${{items.length?items.map(x=>`<li>${{esc(x)}}</li>`).join(''):'<li>待补充。</li>'}}</ul></section>`;i++;}}grid.innerHTML=html;}}
async function generateLesson(){{const btn=document.getElementById('generateBtn');const status=document.getElementById('status');currentInput=buildInput();document.getElementById('taskText').textContent=currentInput;btn.disabled=true;status.textContent='正在转化教案，请稍候……';try{{const res=await fetch(API+'/generate',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'一键转教案',scenario:'教师',input:currentInput}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'生成失败');render((data.data&&data.data.sections)||[]);status.textContent='已转成新教案，可保存或导出。';toast('教案已转化');}}catch(e){{status.textContent='转化失败：'+e.message;toast('转化失败')}}finally{{btn.disabled=false;}}}}
async function saveLesson(){{const btn=document.getElementById('saveBtn');btn.disabled=true;try{{const res=await fetch(API+'/save',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'一键转教案',input:currentInput,sections:currentSections}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'保存失败');toast('已保存到成果库');window.open(data.url,'_blank');}}catch(e){{toast('保存失败：'+e.message)}}finally{{btn.disabled=false;}}}}
function exportText(){{let lines=['一键转教案',currentInput,''];for(const s of currentSections){{lines.push('## '+(s.title||'生成结果'));for(const item of (s.items||[]))lines.push('- '+item);lines.push('');}}const blob=new Blob([lines.join('\\n')],{{type:'text/plain;charset=utf-8'}});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='一键转教案.txt';a.click();URL.revokeObjectURL(a.href);toast('已导出文本')}}
function resetDemo(){{document.getElementById('stage').value='七年级';document.getElementById('subject').value='数学';document.getElementById('topic').value='数轴';document.getElementById('materialType').value='课堂逐字稿';document.getElementById('strategy').value='保留关键教学信息，补齐完整教案';document.getElementById('sourceText').value='老师：今天我们用温度计和楼层图来认识数轴。先看0在哪里，向右表示正方向，向左表示负方向。学生回答：正数在右边，负数在左边。老师追问：如果每一格长度不一样，还能准确表示数吗？接着小组用纸带画数轴，标出-3、0、2、1.5，并比较大小。最后做当堂检测，在数轴上表示-1/2和3。';toast('已恢复示例材料')}}
function hydrateFormFromInput(){{const text=String(currentInput||'');if(text.includes('秦统一')||text.includes('郡县制')||text.includes('统一文字')){{document.getElementById('subject').value='历史';document.getElementById('topic').value='秦统一中国';document.getElementById('materialType').value=text.includes('课堂实录')?'课堂实录':'课堂逐字稿';document.getElementById('sourceText').value=text.replace(/^请把以下[^：:]*[：:]/,'').replace(/^请把[\s\S]*?原始材料[：:]/,'').trim()||text;}}else if(text.includes('水蒸气')||text.includes('三态')){{document.getElementById('subject').value='科学';document.getElementById('topic').value='水的三态变化';document.getElementById('sourceText').value=text;}}else if(text.includes('数轴')){{document.getElementById('subject').value='数学';document.getElementById('topic').value='数轴';}}}}
document.getElementById('generateBtn').addEventListener('click',generateLesson);document.getElementById('saveBtn').addEventListener('click',saveLesson);document.getElementById('exportBtn').addEventListener('click',exportText);document.getElementById('resetBtn').addEventListener('click',resetDemo);hydrateFormFromInput();
</script></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"converted-lesson-plan-system"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"

def write_open_class_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    ensure_generated_dir()
    aid=new_artifact_id(app)
    def section(title):
        for s in sections:
            if str(s.get('title','')) == title:
                return [str(x) for x in s.get('items',[])]
        return []
    order=['公开课定位','教学目标','学情与重难点','核心问题链','学生探究活动','展示评价','板书设计','公开课亮点','风险预案与磨课建议']
    icons={'公开课定位':'🎯','教学目标':'🏁','学情与重难点':'👥','核心问题链':'❓','学生探究活动':'🧪','展示评价':'🗣️','板书设计':'🧩','公开课亮点':'✨','风险预案与磨课建议':'🛡️'}
    cards=[]
    for idx,title in enumerate(order,1):
        items=section(title)
        lis=''.join(f"<li>{html.escape(i)}</li>" for i in items) or '<li>待补充。</li>'
        wide=' wide' if title in ('核心问题链','学生探究活动','风险预案与磨课建议') else ''
        cards.append(f"<section class='card{wide}'><div class='card-head'><span>{icons.get(title,'📌')}</span><div><em>{idx:02d}</em><h2>{html.escape(title)}</h2></div></div><ul>{lis}</ul></section>")
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 公开课教学设计</title><style>body{{margin:0;background:#f8fafc;color:#111827;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:46px 58px;background:radial-gradient(circle at 82% 15%,rgba(168,85,247,.32),transparent 28%),linear-gradient(135deg,#312e81,#7c3aed);color:#fff}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.30);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:900;font-size:13px}}h1{{font-size:43px;margin:18px 0 10px;letter-spacing:-.04em}}.hero p{{max-width:980px;opacity:.93;line-height:1.75}}main{{max-width:1240px;margin:0 auto;padding:28px}}.task{{background:#fff;border:1px solid #ddd6fe;border-radius:28px;padding:22px;margin-bottom:20px;box-shadow:0 18px 44px rgba(49,46,129,.08)}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}.card{{background:#fff;border:1px solid #ddd6fe;border-radius:26px;padding:22px;box-shadow:0 16px 38px rgba(49,46,129,.065)}}.card.wide{{grid-column:span 2}}.card-head{{display:flex;gap:12px;align-items:center;margin-bottom:12px}}.card-head span{{display:grid;place-items:center;width:42px;height:42px;border-radius:16px;background:#f3e8ff;font-size:20px}}.card-head em{{font-style:normal;font-size:12px;color:#6d28d9;font-weight:950;letter-spacing:.08em}}h2{{margin:2px 0 0;color:#5b21b6;font-size:23px}}li{{margin:10px 0;line-height:1.78;color:#374151}}.summary{{border-left:6px solid #7c3aed;background:#faf5ff}}.meta{{font-size:13px;color:#64748b;margin-top:18px}}@media(max-width:860px){{.hero{{padding:30px 22px}}h1{{font-size:32px}}main{{padding:18px}}.grid{{grid-template-columns:1fr}}.card.wide{{grid-column:auto}}}}
</style></head><body><header class='hero'><div class='eyebrow'>公开课教案 · 可观摩可磨课</div><h1>{html.escape(app)}</h1><p>面向公开课场景生成完整教学设计：核心问题链、学生探究活动、展示评价、板书设计、公开课亮点和风险预案形成闭环。</p></header><main><section class='task'><h2>原始公开课任务</h2><p>{html.escape(safe_public_text(input_text))}</p></section><div class='grid'>{''.join(cards)}</div><section class='card summary' style='margin-top:18px'><div class='card-head'><span>✅</span><div><em>OPEN CLASS STANDARD</em><h2>公开课达标标准</h2></div></div><ul><li>公开课要能展示学生真实学习过程。</li><li>每个活动都要紧扣核心问题链。</li><li>课堂亮点要能在现场被观摩者看见。</li></ul></section><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用</div></main></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"open-class-lesson-plan"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"


def write_writing_feedback_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    ensure_generated_dir()
    aid=new_artifact_id(app)
    def section(title):
        for s in sections:
            if str(s.get('title','')) == title:
                return [str(x) for x in s.get('items',[])]
        return []
    order=['总体判断','量表评价','具体亮点','主要问题','不代写修改建议','局部示例','鼓励性评语']
    icons={'总体判断':'🧭','量表评价':'📏','具体亮点':'🌟','主要问题':'🔍','不代写修改建议':'✍️','局部示例':'💡','鼓励性评语':'💬'}
    cards=[]
    for idx,title in enumerate(order,1):
        items=section(title)
        lis=''.join(f"<li>{html.escape(i)}</li>" for i in items) or '<li>待补充。</li>'
        wide=' wide' if title in ('不代写修改建议','鼓励性评语') else ''
        cards.append(f"<section class='card{wide}'><div class='card-head'><span>{icons.get(title,'📌')}</span><div><em>{idx:02d}</em><h2>{html.escape(title)}</h2></div></div><ul>{lis}</ul></section>")
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 作文反馈诊断报告</title><style>body{{margin:0;background:#fff7ed;color:#1f2937;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:44px 56px;background:radial-gradient(circle at 82% 16%,rgba(251,146,60,.34),transparent 28%),linear-gradient(135deg,#7c2d12,#ea580c);color:#fff}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:900;font-size:13px}}h1{{font-size:42px;margin:18px 0 10px;letter-spacing:-.04em}}.hero p{{max-width:960px;opacity:.92;line-height:1.75}}main{{max-width:1220px;margin:0 auto;padding:28px}}.task{{background:#fff;border:1px solid #fed7aa;border-radius:26px;padding:22px;margin-bottom:20px;box-shadow:0 18px 42px rgba(124,45,18,.08)}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}.card{{background:#fff;border:1px solid #fed7aa;border-radius:26px;padding:22px;box-shadow:0 16px 38px rgba(124,45,18,.07)}}.card.wide{{grid-column:span 2}}.card-head{{display:flex;gap:12px;align-items:center;margin-bottom:12px}}.card-head span{{display:grid;place-items:center;width:42px;height:42px;border-radius:16px;background:#ffedd5;font-size:20px}}.card-head em{{font-style:normal;font-size:12px;color:#9a3412;font-weight:950;letter-spacing:.08em}}h2{{margin:2px 0 0;color:#9a3412;font-size:23px}}li{{margin:10px 0;line-height:1.78;color:#374151}}.guard{{border-left:6px solid #ea580c;background:#fff7ed}}.meta{{font-size:13px;color:#78716c;margin-top:18px}}@media(max-width:860px){{.hero{{padding:30px 22px}}h1{{font-size:32px}}main{{padding:18px}}.grid{{grid-template-columns:1fr}}.card.wide{{grid-column:auto}}}}
</style></head><body><header class='hero'><div class='eyebrow'>小学语文作文批改 · 不代写反馈</div><h1>{html.escape(app)}</h1><p>把学生习作转化为可讲评、可订正、可继续写的反馈报告：先肯定真实表达，再指出关键问题，只给修改方向和局部示例，不替学生整篇改写。</p></header><main><section class='task'><h2>原始作文任务</h2><p>{html.escape(safe_public_text(input_text))}</p></section><div class='grid'>{''.join(cards)}</div><section class='card guard' style='margin-top:18px'><div class='card-head'><span>🛡️</span><div><em>WRITING ETHICS</em><h2>批改边界</h2></div></div><ul><li>本报告只做诊断、提示和局部示例，不替学生完成整篇作文。</li><li>教师可把建议变成旁批，让学生保留自己的语言继续修改。</li><li>评价聚焦文本，不对学生做标签化判断。</li></ul></section><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用</div></main></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"writing-feedback-report"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"


def write_lesson_plan_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    """Interactive closed-loop mini system for lesson-plan design.

    The page is not only a static artifact: it keeps a business form, generate,
    save, export, and artifact-library loop so the app behaves like a standalone
    tool system, matching the reference product advantage.
    """
    ensure_generated_dir()
    aid=new_artifact_id(app)
    def section(title):
        for s in sections:
            if str(s.get('title','')) == title:
                return [str(x) for x in s.get('items',[])]
        return []
    order=['教学目标','学情分析','教学重难点','问题链设计','课堂流程','活动设计','评价与作业','板书与资源准备']
    icons={'教学目标':'🎯','学情分析':'👥','教学重难点':'⭐','问题链设计':'❓','课堂流程':'🧭','活动设计':'🧪','评价与作业':'✅','板书与资源准备':'🧰'}
    cards=[]
    for idx,title in enumerate(order,1):
        items=section(title)
        lis=''.join(f"<li>{html.escape(safe_public_text(i))}</li>" for i in items) or '<li>待补充。</li>'
        wide=' wide' if title in ('课堂流程','活动设计') else ''
        cards.append(f"<section class='result-card{wide}' data-section='{html.escape(title)}'><div class='card-head'><span>{icons.get(title,'📌')}</span><div><em>{idx:02d}</em><h2>{html.escape(title)}</h2></div></div><ul>{lis}</ul></section>")
    initial_sections=json.dumps(sections, ensure_ascii=False)
    initial_input=json.dumps(input_text, ensure_ascii=False)
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 独立教案设计小系统</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f5f8ff;color:#101828;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:44px 56px;background:radial-gradient(circle at 82% 16%,rgba(96,165,250,.32),transparent 28%),linear-gradient(135deg,#172554,#3157d5);color:#fff;position:relative;overflow:hidden}}.hero:after{{content:'';position:absolute;right:-90px;top:-90px;width:320px;height:320px;border-radius:50%;background:rgba(255,255,255,.13)}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:950;font-size:13px}}h1{{font-size:42px;margin:18px 0 10px;letter-spacing:-.04em}}.hero p{{max-width:960px;opacity:.93;line-height:1.75}}.hero-actions{{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}}.hero-actions a,.hero-actions button{{appearance:none;border:0;background:#fff;color:#1d4ed8;text-decoration:none;border-radius:16px;padding:12px 16px;font-weight:950;box-shadow:0 12px 26px rgba(15,23,42,.14);cursor:pointer}}main{{max-width:1320px;margin:0 auto;padding:28px}}.system-grid{{display:grid;grid-template-columns:minmax(360px,.78fr) minmax(0,1.22fr);gap:20px;align-items:start}}.panel{{background:#fff;border:1px solid #dbeafe;border-radius:28px;box-shadow:0 18px 44px rgba(23,37,84,.07)}}.form-panel{{position:sticky;top:18px;padding:22px}}.panel-title{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}}.panel-title h2{{margin:0;color:#1d4ed8;font-size:24px}}.badge{{display:inline-flex;align-items:center;border-radius:999px;background:#eff6ff;color:#1d4ed8;padding:7px 10px;font-weight:950;font-size:12px}}label{{display:block;font-size:13px;color:#475569;font-weight:900;margin:14px 0 7px}}input,select,textarea{{width:100%;border:1px solid #c7d2fe;background:#f8fbff;border-radius:16px;padding:12px 13px;font:inherit;color:#111827;outline:none}}textarea{{min-height:128px;resize:vertical;line-height:1.6}}input:focus,select:focus,textarea:focus{{border-color:#3157d5;box-shadow:0 0 0 4px rgba(49,87,213,.12)}}.field-row{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.btn-row{{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;margin-top:18px}}button.primary,button.secondary,button.ghost{{appearance:none;border:0;border-radius:16px;padding:13px 14px;font-weight:950;cursor:pointer}}button.primary{{background:#3157d5;color:#fff;box-shadow:0 14px 28px rgba(49,87,213,.24)}}button.secondary{{background:#0f766e;color:#fff}}button.ghost{{background:#eef4ff;color:#1d4ed8}}button:disabled{{opacity:.58;cursor:not-allowed}}.tips{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}}.tips span{{background:#eef4ff;color:#1e3a8a;border-radius:14px;padding:10px;font-size:12px;font-weight:800;line-height:1.45}}.result-panel{{padding:0;overflow:hidden}}.result-head{{padding:22px 24px;border-bottom:1px solid #e5e7eb;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:linear-gradient(180deg,#fff,#f8fbff)}}.result-head h2{{margin:0;color:#172554;font-size:25px}}.status{{font-size:13px;color:#64748b;font-weight:800}}.task{{margin:20px 24px;background:#fff;border:1px solid #bfdbfe;border-radius:24px;padding:20px;box-shadow:0 12px 28px rgba(23,37,84,.045)}}.task h3{{margin:0 0 10px;color:#1d4ed8}}.task p{{line-height:1.75;color:#334155;white-space:pre-wrap}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;padding:0 24px 24px}}.result-card{{background:#fff;border:1px solid #dbeafe;border-radius:24px;padding:20px;box-shadow:0 14px 34px rgba(23,37,84,.055)}}.result-card.wide{{grid-column:span 2}}.card-head{{display:flex;gap:12px;align-items:center;margin-bottom:12px}}.card-head span{{display:grid;place-items:center;width:42px;height:42px;border-radius:16px;background:#eef4ff;font-size:20px}}.card-head em{{font-style:normal;font-size:12px;color:#64748b;font-weight:950;letter-spacing:.08em}}.result-card h2{{margin:2px 0 0;color:#1d4ed8;font-size:22px}}li{{margin:10px 0;line-height:1.78;color:#334155}}.closed-loop{{margin:0 24px 24px;border-left:6px solid #3157d5;background:#eff6ff;border-radius:22px;padding:18px;color:#1e3a8a;line-height:1.72}}.toast{{position:fixed;right:20px;bottom:20px;background:#111827;color:#fff;border-radius:16px;padding:13px 16px;box-shadow:0 16px 40px rgba(15,23,42,.28);font-weight:900;opacity:0;transform:translateY(10px);transition:.2s;z-index:20}}.toast.show{{opacity:1;transform:translateY(0)}}.meta{{font-size:13px;color:#64748b;margin:0 24px 24px}}@media(max-width:980px){{.hero{{padding:32px 22px}}h1{{font-size:32px}}main{{padding:18px}}.system-grid{{grid-template-columns:1fr}}.form-panel{{position:static}}.grid{{grid-template-columns:1fr}}.result-card.wide{{grid-column:auto}}.tips{{grid-template-columns:1fr}}}}@media(max-width:560px){{.field-row,.btn-row{{grid-template-columns:1fr}}}}

</style></head><body><header class='hero'><div class='eyebrow'>教案设计 · 独立业务闭环小系统</div><h1>{html.escape(app)}</h1><p>这不是单纯结果页：老师可以在左侧填写学段、学科、课题、课型、课时与学情，点击生成后得到完整教案，并可保存到官方工具成果库、导出文本、继续重生成。</p><div class='hero-actions'><a href='{PUBLIC_BASE}/index.html' target='_blank'>打开成果库</a><button type='button' onclick='document.getElementById("topic").focus()'>开始设计教案</button></div></header><main><div class='system-grid'><aside class='panel form-panel'><div class='panel-title'><h2>业务参数</h2><span class='badge'>闭环表单</span></div><label for='stage'>学段</label><div class='field-row'><select id='stage'><option>七年级</option><option>小学四年级</option><option>小学五年级</option><option>八年级</option><option>高一</option></select><select id='subject'><option>数学</option><option>语文</option><option>历史</option><option>科学</option><option>英语</option></select></div><label for='topic'>课题</label><input id='topic' value='数轴' placeholder='例如：数轴、秦统一中国、猫'><div class='field-row'><div><label for='lessonType'>课型</label><select id='lessonType'><option>新授课</option><option>复习课</option><option>公开课</option><option>讲评课</option></select></div><div><label for='duration'>课时</label><select id='duration'><option>40分钟</option><option>45分钟</option><option>1课时</option><option>2课时</option></select></div></div><label for='focus'>设计侧重</label><select id='focus'><option>问题链 + 学生活动 + 评价闭环</option><option>核心素养目标 + 教学评一体化</option><option>公开课展示感 + 风险预案</option><option>基础薄弱班级的支架设计</option></select><label for='learning'>学情与要求</label><textarea id='learning' placeholder='写清学生基础、常见误区、课堂要求、必须包含的活动或评价。'>学生已有正负数经验，但容易混淆方向、距离和大小；要求有生活情境导入、学生操作活动、问题链、当堂检测和板书设计。</textarea><div class='btn-row'><button class='primary' id='generateBtn' type='button'>生成教案</button><button class='secondary' id='saveBtn' type='button'>保存成果</button></div><div class='btn-row'><button class='ghost' id='exportBtn' type='button'>导出文本</button><button class='ghost' id='resetBtn' type='button'>恢复示例</button></div><div class='tips'><span>入口：明确课题与课型</span><span>生成：调用后端模型代理</span><span>闭环：保存/导出/成果库</span></div></aside><section class='panel result-panel'><div class='result-head'><h2>当前教案成果</h2><div class='status' id='status'>已加载一份可上课教案，可继续重生成。</div></div><section class='task'><h3>原始任务</h3><p id='taskText'>{html.escape(safe_public_text(input_text))}</p></section><div class='grid' id='resultGrid'>{''.join(cards)}</div><section class='closed-loop'><b>业务闭环说明：</b>本应用已具备“填写教案业务参数 → 一键生成 → 结构化教案 → 保存到成果库 → 导出文本 → 再次修改重生成”的完整小系统流程。</section><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用 · artifact_id={html.escape(aid)}</div></section></div></main><div class='toast' id='toast'></div><script>
const API='/wendui-engine-api';
let currentSections={initial_sections};
let currentInput={initial_input};
const order={json.dumps(order, ensure_ascii=False)};
const icons={json.dumps(icons, ensure_ascii=False)};
function toast(msg){{const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}}
function buildInput(){{const v=id=>document.getElementById(id).value.trim();return `请为${{v('stage')}}${{v('subject')}}《${{v('topic')}}》设计一份${{v('duration')}}${{v('lessonType')}}教案。设计侧重：${{v('focus')}}。学情与要求：${{v('learning')}}。必须包含教学目标、学情分析、教学重难点、问题链设计、课堂流程、活动设计、评价与作业、板书与资源准备。`;}}
function esc(s){{return String(s||'').replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]))}}
function render(sections){{currentSections=sections||[];const grid=document.getElementById('resultGrid');const map=new Map(currentSections.map(s=>[String(s.title||''),Array.isArray(s.items)?s.items:[]]));let html='';let i=1;for(const title of order){{const items=map.get(title)||[];const wide=(title==='课堂流程'||title==='活动设计')?' wide':'';html+=`<section class="result-card${{wide}}"><div class="card-head"><span>${{icons[title]||'📌'}}</span><div><em>${{String(i).padStart(2,'0')}}</em><h2>${{esc(title)}}</h2></div></div><ul>${{items.length?items.map(x=>`<li>${{esc(x)}}</li>`).join(''):'<li>待补充。</li>'}}</ul></section>`;i++;}}grid.innerHTML=html;}}
async function generateLesson(){{const btn=document.getElementById('generateBtn');const status=document.getElementById('status');currentInput=buildInput();document.getElementById('taskText').textContent=currentInput;btn.disabled=true;status.textContent='正在生成教案，请稍候……';try{{const res=await fetch(API+'/generate',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'教案设计',scenario:'教师',input:currentInput}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'生成失败');render((data.data&&data.data.sections)||[]);status.textContent='已生成新教案，可保存或导出。';toast('教案已生成');}}catch(e){{status.textContent='生成失败：'+e.message;toast('生成失败')}}finally{{btn.disabled=false;}}}}
async function saveLesson(){{const btn=document.getElementById('saveBtn');btn.disabled=true;try{{const res=await fetch(API+'/save',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'教案设计',input:currentInput,sections:currentSections}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'保存失败');toast('已保存到成果库');window.open(data.url,'_blank');}}catch(e){{toast('保存失败：'+e.message)}}finally{{btn.disabled=false;}}}}
function exportText(){{let lines=['教案设计',currentInput,''];for(const s of currentSections){{lines.push('## '+(s.title||'生成结果'));for(const item of (s.items||[]))lines.push('- '+item);lines.push('');}}const blob=new Blob([lines.join('\\n')],{{type:'text/plain;charset=utf-8'}});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='教案设计.txt';a.click();URL.revokeObjectURL(a.href);toast('已导出文本')}}
function resetDemo(){{document.getElementById('stage').value='七年级';document.getElementById('subject').value='数学';document.getElementById('topic').value='数轴';document.getElementById('lessonType').value='新授课';document.getElementById('duration').value='40分钟';document.getElementById('focus').value='问题链 + 学生活动 + 评价闭环';document.getElementById('learning').value='学生已有正负数经验，但容易混淆方向、距离和大小；要求有生活情境导入、学生操作活动、问题链、当堂检测和板书设计。';toast('已恢复示例参数')}}
document.getElementById('generateBtn').addEventListener('click',generateLesson);document.getElementById('saveBtn').addEventListener('click',saveLesson);document.getElementById('exportBtn').addEventListener('click',exportText);document.getElementById('resetBtn').addEventListener('click',resetDemo);
</script></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"complete-lesson-plan-system"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"

def write_quiz_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    ensure_generated_dir()
    aid=new_artifact_id(app)
    def clean_math_text(v: str) -> str:
        v=str(v or '')
        replacements={
            '\\(':'', '\\)':'', '\\\\(':'', '\\\\)':'',
            '\\vert':'|', '\\\\vert':'|', '\\times':'×', '\\\\times':'×',
            '\\div':'÷', '\\\\div':'÷', '\\le':'≤', '\\\\le':'≤',
            '\\ge':'≥', '\\\\ge':'≥', '\\neq':'≠', '\\\\neq':'≠',
        }
        for old,new in replacements.items():
            v=v.replace(old,new)
        v=re.sub(r'\\+([{}\[\]])', r'\1', v)
        v=re.sub(r'\\+', '', v)
        return v
    def sec(title):
        for s in sections:
            if str(s.get('title','')) == title:
                return [clean_math_text(str(x)) for x in s.get('items',[])]
        return []
    order=['基础题','提升题','综合题','答案解析','讲评提示','梯度总结']
    icons={'基础题':'①','提升题':'②','综合题':'③','答案解析':'✓','讲评提示':'💬','梯度总结':'↗'}
    cards=[]
    for title in order:
        items=sec(title)
        lis=''.join(f"<li>{html.escape(i)}</li>" for i in items) or '<li>待补充。</li>'
        cards.append(f"<section class='card {title}'><div class='card-head'><span>{icons.get(title,'📌')}</span><h2>{html.escape(title)}</h2></div><ul>{lis}</ul></section>")
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 分层练习题单</title><style>body{{margin:0;background:#f8fafc;color:#101828;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:42px 54px;background:radial-gradient(circle at 82% 14%,rgba(34,197,94,.28),transparent 28%),linear-gradient(135deg,#064e3b,#059669);color:#fff}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:900;font-size:13px}}h1{{font-size:40px;margin:18px 0 10px}}.hero p{{max-width:900px;opacity:.92;line-height:1.7}}main{{max-width:1180px;margin:0 auto;padding:28px}}.task{{background:#fff;border:1px solid #bbf7d0;border-radius:24px;padding:22px;margin-bottom:20px;box-shadow:0 16px 38px rgba(6,78,59,.06)}}.grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}}.card{{background:#fff;border:1px solid #bbf7d0;border-radius:24px;padding:22px;box-shadow:0 14px 34px rgba(6,78,59,.06)}}.card-head{{display:flex;gap:10px;align-items:center;margin-bottom:10px}}.card-head span{{display:grid;place-items:center;width:38px;height:38px;border-radius:14px;background:#dcfce7;color:#047857;font-weight:950}}h2{{margin:0;color:#047857;font-size:22px}}li{{margin:10px 0;line-height:1.72;color:#334155}}.基础题{{border-top:6px solid #22c55e}}.提升题{{border-top:6px solid #0ea5e9}}.综合题{{border-top:6px solid #f97316}}.wide{{grid-column:span 3}}.meta{{font-size:13px;color:#64748b;margin-top:18px}}@media(max-width:900px){{.grid{{grid-template-columns:1fr}}.wide{{grid-column:auto}}.hero{{padding:30px 22px}}main{{padding:18px}}}}
</style></head><body><header class='hero'><div class='eyebrow'>知识点出题 · 基础—提升—综合</div><h1>{html.escape(app)}</h1><p>把一个知识点转化为可直接课堂使用的分层练习题单，包含答案解析、讲评提示和梯度总结。</p></header><main><section class='task'><h2>原始出题任务</h2><p>{html.escape(safe_public_text(input_text))}</p></section><div class='grid'>{''.join(cards[:3])}<section class='card wide'><div class='card-head'><span>✓</span><h2>答案解析、讲评与梯度总结</h2></div>{''.join('<h3>'+html.escape(t)+'</h3><ul>'+''.join(f'<li>{html.escape(i)}</li>' for i in sec(t))+'</ul>' for t in ['答案解析','讲评提示','梯度总结'])}</section></div><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用</div></main></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"leveled-quiz-sheet"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"



def write_speech_artifact_html(app: str, input_text: str, sections: list[dict]) -> tuple[str, str]:
    """Interactive closed-loop mini system for teacher speech-script generation."""
    ensure_generated_dir()
    aid=new_artifact_id(app)
    order=['说教材','说学情','说目标','说重难点','说教法学法','说教学过程','说板书','说评价反思']
    icons={'说教材':'📚','说学情':'👥','说目标':'🎯','说重难点':'⭐','说教法学法':'🧭','说教学过程':'🎤','说板书':'🧩','说评价反思':'✅'}
    secmap={str(x.get('title','')):[str(i) for i in (x.get('items') or [])] for x in sections if isinstance(x,dict)}
    def items_for(t): return secmap.get(t) or []
    cards=[]
    for idx,title in enumerate(order,1):
        items=items_for(title)
        lis=''.join(f"<li>{html.escape(safe_public_text(i))}</li>" for i in items) or '<li>待补充。</li>'
        wide=' wide' if title in ('说教学过程','说教材') else ''
        cards.append(f"<section class='result-card{wide}' data-section='{html.escape(title)}'><div class='card-head'><span>{icons.get(title,'📌')}</span><div><em>{idx:02d}</em><h2>{html.escape(title)}</h2></div></div><ul>{lis}</ul></section>")
    initial_sections=json.dumps(sections, ensure_ascii=False)
    initial_input=json.dumps(input_text, ensure_ascii=False)
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(app)} · 独立说课稿生成小系统</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f8fafc;color:#101828;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}}.hero{{padding:44px 56px;background:radial-gradient(circle at 82% 16%,rgba(148,163,184,.34),transparent 30%),linear-gradient(135deg,#111827,#475569);color:#fff;position:relative;overflow:hidden}}.hero:after{{content:'';position:absolute;right:-100px;top:-100px;width:330px;height:330px;border-radius:50%;background:rgba(255,255,255,.12)}}.eyebrow{{display:inline-flex;border:1px solid rgba(255,255,255,.30);background:rgba(255,255,255,.13);border-radius:999px;padding:7px 12px;font-weight:950;font-size:13px}}h1{{font-size:42px;margin:18px 0 10px;letter-spacing:-.04em}}.hero p{{max-width:980px;opacity:.93;line-height:1.75}}.hero-actions{{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}}.hero-actions a,.hero-actions button{{appearance:none;border:0;background:#fff;color:#334155;text-decoration:none;border-radius:16px;padding:12px 16px;font-weight:950;box-shadow:0 12px 26px rgba(15,23,42,.14);cursor:pointer}}main{{max-width:1340px;margin:0 auto;padding:28px}}.system-grid{{display:grid;grid-template-columns:minmax(380px,.82fr) minmax(0,1.18fr);gap:20px;align-items:start}}.panel{{background:#fff;border:1px solid #e2e8f0;border-radius:28px;box-shadow:0 18px 44px rgba(15,23,42,.07)}}.form-panel{{position:sticky;top:18px;padding:22px}}.panel-title{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}}.panel-title h2{{margin:0;color:#334155;font-size:24px}}.badge{{display:inline-flex;align-items:center;border-radius:999px;background:#e2e8f0;color:#334155;padding:7px 10px;font-weight:950;font-size:12px}}label{{display:block;font-size:13px;color:#475569;font-weight:900;margin:14px 0 7px}}input,select,textarea{{width:100%;border:1px solid #cbd5e1;background:#f8fafc;border-radius:16px;padding:12px 13px;font:inherit;color:#111827;outline:none}}textarea{{min-height:190px;resize:vertical;line-height:1.62}}input:focus,select:focus,textarea:focus{{border-color:#475569;box-shadow:0 0 0 4px rgba(71,85,105,.13)}}.field-row{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.btn-row{{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;margin-top:18px}}button.primary,button.secondary,button.ghost{{appearance:none;border:0;border-radius:16px;padding:13px 14px;font-weight:950;cursor:pointer}}button.primary{{background:#111827;color:#fff;box-shadow:0 14px 28px rgba(15,23,42,.24)}}button.secondary{{background:#3157d5;color:#fff}}button.ghost{{background:#f1f5f9;color:#334155}}button:disabled{{opacity:.58;cursor:not-allowed}}.tips{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}}.tips span{{background:#f1f5f9;color:#334155;border-radius:14px;padding:10px;font-size:12px;font-weight:800;line-height:1.45}}.result-panel{{padding:0;overflow:hidden}}.result-head{{padding:22px 24px;border-bottom:1px solid #e2e8f0;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:linear-gradient(180deg,#fff,#f8fafc)}}.result-head h2{{margin:0;color:#111827;font-size:25px}}.status{{font-size:13px;color:#64748b;font-weight:800}}.task{{margin:20px 24px;background:#fff;border:1px solid #e2e8f0;border-radius:24px;padding:20px;box-shadow:0 12px 28px rgba(15,23,42,.045)}}.task h3{{margin:0 0 10px;color:#334155}}.task p{{line-height:1.75;color:#334155;white-space:pre-wrap}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;padding:0 24px 24px}}.result-card{{background:#fff;border:1px solid #e2e8f0;border-radius:24px;padding:20px;box-shadow:0 14px 34px rgba(15,23,42,.055)}}.result-card.wide{{grid-column:span 2}}.card-head{{display:flex;gap:12px;align-items:center;margin-bottom:12px}}.card-head span{{display:grid;place-items:center;width:42px;height:42px;border-radius:16px;background:#e2e8f0;font-size:20px}}.card-head em{{font-style:normal;font-size:12px;color:#64748b;font-weight:950;letter-spacing:.08em}}.result-card h2{{margin:2px 0 0;color:#334155;font-size:22px}}li{{margin:10px 0;line-height:1.78;color:#334155}}.closed-loop{{margin:0 24px 24px;border-left:6px solid #475569;background:#f1f5f9;border-radius:22px;padding:18px;color:#334155;line-height:1.72}}.toast{{position:fixed;right:20px;bottom:20px;background:#111827;color:#fff;border-radius:16px;padding:13px 16px;box-shadow:0 16px 40px rgba(15,23,42,.28);font-weight:900;opacity:0;transform:translateY(10px);transition:.2s;z-index:20}}.toast.show{{opacity:1;transform:translateY(0)}}.meta{{font-size:13px;color:#64748b;margin:0 24px 24px}}@media(max-width:980px){{.hero{{padding:32px 22px}}h1{{font-size:32px}}main{{padding:18px}}.system-grid{{grid-template-columns:1fr}}.form-panel{{position:static}}.grid{{grid-template-columns:1fr}}.result-card.wide{{grid-column:auto}}.tips{{grid-template-columns:1fr}}}}@media(max-width:560px){{.field-row,.btn-row{{grid-template-columns:1fr}}}}

</style></head><body><header class='hero'><div class='eyebrow'>说课稿 · 独立教师现场表达小系统</div><h1>{html.escape(app)}</h1><p>把课题、学情、教学设计材料转成教师现场可讲的说课稿。系统强调“为什么这样教、怎样组织学生学、如何证明有效”，并支持重生成、保存成果和导出文本。</p><div class='hero-actions'><a href='{PUBLIC_BASE}/index.html' target='_blank'>打开成果库</a><button type='button' onclick='document.getElementById("topic").focus()'>开始生成说课稿</button></div></header><main><div class='system-grid'><aside class='panel form-panel'><div class='panel-title'><h2>说课参数</h2><span class='badge'>说课闭环</span></div><div class='field-row'><div><label for='stage'>学段</label><select id='stage'><option>七年级</option><option>小学四年级</option><option>小学五年级</option><option>八年级</option><option>高一</option></select></div><div><label for='subject'>学科</label><select id='subject'><option>数学</option><option>语文</option><option>历史</option><option>科学</option><option>英语</option></select></div></div><div class='field-row'><div><label for='topic'>课题</label><input id='topic' value='数轴' placeholder='例如：数轴、秦统一中国'></div><div><label for='occasion'>说课场景</label><select id='occasion'><option>校内教研说课</option><option>公开课赛课说课</option><option>新教师磨课说课</option><option>备课组集体说课</option></select></div></div><div class='field-row'><div><label for='duration'>说课时长</label><select id='duration'><option>8分钟</option><option>10分钟</option><option>12分钟</option><option>15分钟</option></select></div><div><label for='focus'>表达侧重</label><select id='focus'><option>设计理由 + 学生活动 + 评价证据</option><option>教材学情 + 重难点突破</option><option>公开课亮点 + 风险预案</option><option>教学评一体化</option></select></div></div><label for='sourceText'>教学设计材料</label><textarea id='sourceText'>本课为七年级数学《数轴》。学生已有温度计、楼层、方向等生活经验，但容易混淆方向、距离和大小。课堂以温度计和纸带活动导入，让学生发现原点、正方向、单位长度，并通过错例诊断和标点练习完成理解。</textarea><div class='btn-row'><button class='primary' id='generateBtn' type='button'>生成说课稿</button><button class='secondary' id='saveBtn' type='button'>保存成果</button></div><div class='btn-row'><button class='ghost' id='exportBtn' type='button'>导出文本</button><button class='ghost' id='resetBtn' type='button'>恢复示例</button></div><div class='tips'><span>表达：现场可讲而非论文腔</span><span>逻辑：为什么教、怎样学、如何评</span><span>闭环：生成/保存/导出/再修改</span></div></aside><section class='panel result-panel'><div class='result-head'><h2>当前说课稿成果</h2><div class='status' id='status'>已加载一份说课稿，可继续重生成。</div></div><section class='task'><h3>原始说课任务</h3><p id='taskText'>{html.escape(safe_public_text(input_text))}</p></section><div class='grid' id='resultGrid'>{''.join(cards)}</div><section class='closed-loop'><b>业务闭环说明：</b>本应用已具备“填写课题与材料 → 生成说课稿 → 保存到成果库 → 导出文本 → 修改参数再生成”的完整小系统流程。</section><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} · 节点引擎官方工具应用 · artifact_id={html.escape(aid)}</div></section></div></main><div class='toast' id='toast'></div><script>
const API='/wendui-engine-api';
let currentSections={initial_sections};
let currentInput={initial_input};
const order={json.dumps(order, ensure_ascii=False)};
const icons={json.dumps(icons, ensure_ascii=False)};
function toast(msg){{const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}}
function esc(s){{return String(s||'').replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]))}}
function buildInput(){{const v=id=>document.getElementById(id).value.trim();return `请为${{v('stage')}}${{v('subject')}}《${{v('topic')}}》生成一份${{v('duration')}}左右、用于${{v('occasion')}}的说课稿。表达侧重：${{v('focus')}}。要求按说教材、说学情、说目标、说重难点、说教法学法、说教学过程、说板书、说评价反思展开，语言适合教师现场表达。教学设计材料：${{v('sourceText')}}`;}}
function render(sections){{currentSections=sections||[];const map=new Map(currentSections.map(s=>[String(s.title||''),Array.isArray(s.items)?s.items:[]]));let html='';let i=1;for(const title of order){{const items=map.get(title)||[];const wide=(title==='说教学过程'||title==='说教材')?' wide':'';html+=`<section class="result-card${{wide}}"><div class="card-head"><span>${{icons[title]||'📌'}}</span><div><em>${{String(i).padStart(2,'0')}}</em><h2>${{esc(title)}}</h2></div></div><ul>${{items.length?items.map(x=>`<li>${{esc(x)}}</li>`).join(''):'<li>待补充。</li>'}}</ul></section>`;i++;}}document.getElementById('resultGrid').innerHTML=html;}}
async function generateSpeech(){{const btn=document.getElementById('generateBtn');const status=document.getElementById('status');currentInput=buildInput();document.getElementById('taskText').textContent=currentInput;btn.disabled=true;status.textContent='正在生成说课稿，请稍候……';try{{const res=await fetch(API+'/generate',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'说课稿',scenario:'教师',input:currentInput}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'生成失败');render((data.data&&data.data.sections)||[]);status.textContent='已生成新说课稿，可保存或导出。';toast('说课稿已生成');}}catch(e){{status.textContent='生成失败：'+e.message;toast('生成失败')}}finally{{btn.disabled=false;}}}}
async function saveSpeech(){{const btn=document.getElementById('saveBtn');btn.disabled=true;try{{const res=await fetch(API+'/save',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{app:'说课稿',input:currentInput,sections:currentSections}})}});const data=await res.json();if(!data.ok)throw new Error(data.message||data.status||'保存失败');toast('已保存到成果库');window.open(data.url,'_blank');}}catch(e){{toast('保存失败：'+e.message)}}finally{{btn.disabled=false;}}}}
function exportText(){{let lines=['说课稿',currentInput,''];for(const s of currentSections){{lines.push('## '+(s.title||'生成结果'));for(const item of (s.items||[]))lines.push('- '+item);lines.push('');}}const blob=new Blob([lines.join('\\n')],{{type:'text/plain;charset=utf-8'}});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='说课稿.txt';a.click();URL.revokeObjectURL(a.href);toast('已导出文本')}}
function resetDemo(){{document.getElementById('stage').value='七年级';document.getElementById('subject').value='数学';document.getElementById('topic').value='数轴';document.getElementById('occasion').value='校内教研说课';document.getElementById('duration').value='8分钟';document.getElementById('focus').value='设计理由 + 学生活动 + 评价证据';document.getElementById('sourceText').value='本课为七年级数学《数轴》。学生已有温度计、楼层、方向等生活经验，但容易混淆方向、距离和大小。课堂以温度计和纸带活动导入，让学生发现原点、正方向、单位长度，并通过错例诊断和标点练习完成理解。';toast('已恢复示例材料')}}
function hydrateFormFromInput(){{const text=String(currentInput||'');if(text.includes('秦统一')||text.includes('郡县制')||text.includes('统一文字')){{document.getElementById('subject').value='历史';document.getElementById('topic').value='秦统一中国';document.getElementById('sourceText').value=text.replace(/^请为[\\s\\S]*?教学设计材料[：:]/,'').trim()||text;}}else if(text.includes('数轴')){{document.getElementById('subject').value='数学';document.getElementById('topic').value='数轴';}}}}
document.getElementById('generateBtn').addEventListener('click',generateSpeech);document.getElementById('saveBtn').addEventListener('click',saveSpeech);document.getElementById('exportBtn').addEventListener('click',exportText);document.getElementById('resetBtn').addEventListener('click',resetDemo);hydrateFormFromInput();
</script></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
    json_path=GENERATED_DIR/f"{aid}.json"
    path.write_text(doc, encoding='utf-8')
    json_path.write_text(json.dumps({"id":aid,"app":app,"input":input_text,"sections":sections,"created_at":time.time(),"artifact_type":"speech-script-system"}, ensure_ascii=False, indent=2), encoding='utf-8')
    write_artifact_index()
    return aid, f"{PUBLIC_BASE}/{aid}.html"


def write_history_chat_artifact_html(app: str, input_text: str, sections: list[dict], visual_url: str = "") -> tuple[str, str]:
    """YGBH-like saved page for App1: chat workspace + 开始创作 modal."""
    ensure_generated_dir()
    aid=new_artifact_id(app)
    svg_url = str(visual_url or '').strip()
    clean_sections=[]
    for sec in sections or []:
        if not isinstance(sec, dict):
            continue
        title=html.escape(str(sec.get('title','生成结果')))
        items=''.join(f"<li>{html.escape(txt)}</li>" for txt in [safe_public_text(str(i)) for i in (sec.get('items') or [])] if txt)
        clean_sections.append(f"<div class='result-card'><b>{title}</b><ul>{items}</ul></div>")
    cards=''.join(clean_sections) or "<div class='result-card'><b>生成结果</b><ul><li>请点击 开始生成 生成。</li></ul></div>"
    compact_buttons=''.join(f"<button class='section-chip' type='button' data-sec='{idx}'>{html.escape(str((sec or {}).get('title','栏目'+str(idx+1))))}</button>" for idx,sec in enumerate(sections or []))
    compact_json=json.dumps(sections or [], ensure_ascii=False)
    raw_public = safe_public_text(input_text)
    display_public = re.sub(r'不要出现[^。]*。?', '', raw_public)
    display_public = re.sub(r'负面约束[:：][^。]*。?', '', display_public)
    display_public = re.sub(r'不要[^。；;]*[。；;]?', '', display_public)
    display_public = re.sub(r'不应[^。；;]*[。；;]?', '', display_public)
    display_public = re.sub(r'避免[^。；;]*[。；;]?', '', display_public)
    safe_input=html.escape(display_public[:900])
    scene_val=html.escape(display_public.replace('应用：历史情景插图。','').replace('请生成课堂可用的视觉插图方案，包含画面理解、主体元素、构图层次、知识点标注、生图提示词和课堂追问。','')[:220])
    visual_block = ''
    if svg_url:
        visual_block = f"<div class='image-preview-card'><div class='preview-head'><span>真实图片生成</span><span>点击图片全屏查看</span></div><img src='{html.escape(svg_url)}' alt='历史情景插图真实图片' onclick=\"openLightbox('{html.escape(svg_url)}')\"></div>"
    doc=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>历史情景插图</title><style>
*{{box-sizing:border-box}}html,body{{margin:0;min-height:100%;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',Arial,sans-serif;background:#eef2f7;color:#1f2937}}.app{{min-height:100dvh;display:grid;grid-template-rows:68px 1fr}}.top{{height:68px;background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;padding:0 24px;box-shadow:0 1px 0 rgba(15,23,42,.03)}}.brand{{display:flex;align-items:center;gap:12px;font-weight:900;font-size:20px}}.icon{{width:42px;height:42px;border-radius:14px;background:linear-gradient(135deg,#e7f6e9,#cdebd0);display:grid;place-items:center;font-size:23px}}.brand small{{display:block;font-size:12px;font-weight:800;color:#64748b;margin-top:2px}}.top a,.top button{{border:1px solid #dbe3ef;background:#fff;border-radius:12px;padding:9px 12px;color:#334155;font-weight:800;text-decoration:none;cursor:pointer}}.workspace{{min-height:calc(100dvh - 68px);display:block}}.chat{{position:relative;background:#f4f6fa;min-width:0}}.chat-scroll{{padding:28px 34px 120px}}.message{{display:flex;gap:14px;margin:16px 0;align-items:flex-start}}.avatar{{width:44px;height:44px;flex:0 0 44px;border-radius:14px;background:linear-gradient(135deg,#e4f7df,#bfe6c1);display:grid;place-items:center;font-size:24px;box-shadow:0 12px 22px rgba(21,128,61,.12)}}.bubble{{max-width:min(920px,86%);background:#fff;border:1px solid #e6ebf3;border-radius:20px;padding:20px 22px;box-shadow:0 14px 38px rgba(15,23,42,.06)}}.bubble h2{{margin:0 0 10px;color:#3157d5;font-size:26px}}.bubble p{{margin:0 0 12px;line-height:1.72;color:#4b5563}}.suggestions{{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}}.suggestions button{{border:1px solid #dbeafe;background:#eff6ff;color:#1d4ed8;border-radius:14px;padding:10px 13px;font-weight:800;cursor:pointer}}.result-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:16px}}.result-card{{border:1px solid #e6ebf3;border-radius:16px;background:#fbfdff;padding:14px}}.result-card b{{display:block;color:#1f2937;margin-bottom:8px}}.result-card ul{{margin:0;padding-left:18px}}.result-card li{{margin:6px 0;line-height:1.62;color:#475569}}.composer{{position:fixed;left:28px;right:388px;bottom:24px;background:#fff;border:1px solid #e5e7eb;border-radius:24px;box-shadow:0 22px 60px rgba(15,23,42,.12);display:grid;grid-template-columns:1fr 54px;align-items:end;padding:12px}}.composer textarea{{border:0;outline:0;resize:none;min-height:52px;max-height:120px;padding:13px 14px;font:inherit;line-height:1.55;color:#334155}}.send{{width:48px;height:48px;border:0;border-radius:50%;background:#2563eb;color:white;font-size:22px;font-weight:900;cursor:pointer}}.side{{background:#fff;border-left:1px solid #e5e7eb;padding:22px;overflow:auto}}.side h3{{margin:0 0 12px;font-size:18px}}.preview{{border:1px solid #e6ebf3;border-radius:22px;background:#fffaf0;min-height:250px;padding:16px;box-shadow:0 12px 28px rgba(120,53,15,.07)}}.preview iframe{{width:100%;height:230px;border:0;border-radius:16px;background:white}}.image-preview-card{{margin-top:16px;border:1px solid #e5e7eb;border-radius:16px;overflow:hidden;background:#fff}}.image-preview-card .preview-head{{padding:10px 12px;font-weight:900;color:#334155;background:#f8fafc;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between}}.image-preview-card img{{width:100%;max-height:620px;object-fit:contain;display:block;background:#0f172a;cursor:zoom-in}}.lightbox{{position:fixed;inset:0;background:rgba(2,6,23,.92);z-index:9999;display:none;align-items:center;justify-content:center;padding:28px}}.lightbox.show{{display:flex}}.lightbox img{{max-width:96vw;max-height:92vh;object-fit:contain;border-radius:14px}}.lightbox button{{position:absolute;right:24px;top:20px;border:0;border-radius:999px;background:rgba(255,255,255,.92);color:#0f172a;font-size:18px;font-weight:900;padding:10px 14px;cursor:pointer}}.tools{{display:grid;gap:10px;margin-top:16px}}.tools button,.tools a{{border:0;border-radius:14px;padding:12px 14px;font-weight:900;text-align:center;text-decoration:none;cursor:pointer}}.primary{{background:#3157d5;color:#fff}}.secondary{{background:#0f766e;color:#fff}}.ghost{{background:#f1f5f9;color:#334155}}.meta{{font-size:12px;color:#64748b;line-height:1.6;margin-top:16px}}.modal-mask{{position:fixed;inset:0;background:rgba(15,23,42,.45);display:none;align-items:center;justify-content:center;z-index:50}}.modal-mask.show{{display:flex}}.modal{{width:min(390px,calc(100vw - 32px));background:#fff;border-radius:8px;padding:24px 20px 20px;box-shadow:0 24px 80px rgba(15,23,42,.25);position:relative}}.modal h2{{margin:0 0 14px;font-size:25px;color:#333}}.modal .desc{{font-size:14px;color:#333;line-height:1.45;margin-bottom:16px}}.close{{position:absolute;right:16px;top:14px;border:0;background:transparent;font-size:25px;color:#333;cursor:pointer}}.field{{margin:16px 0}}.field label{{display:block;font-size:14px;color:#404040;margin-bottom:8px}}.field label em{{color:#ef4444;font-style:normal;margin-right:4px}}.field textarea,.field select{{width:100%;border:1px solid #d9dee8;border-radius:5px;padding:12px 14px;font:inherit;color:#4b5563;background:#fff;outline:none}}.field textarea{{min-height:64px;resize:vertical}}.ai-btn{{display:flex;align-items:center;justify-content:center;gap:8px;margin:20px auto 4px;border:0;border-radius:999px;padding:13px 28px;background:linear-gradient(90deg,#6d63ff,#55c7df);color:#fff;font-size:16px;font-weight:800;cursor:pointer}}.toast{{position:fixed;left:50%;bottom:28px;transform:translateX(-50%) translateY(20px);background:#111827;color:#fff;border-radius:14px;padding:10px 14px;opacity:0;pointer-events:none;transition:.2s;z-index:80}}.toast.show{{opacity:1;transform:translateX(-50%) translateY(0)}}@media(max-width:980px){{.workspace{{grid-template-columns:1fr}}.side{{display:none}}.composer{{left:14px;right:14px}}.result-grid{{grid-template-columns:1fr}}}}
.result-grid.compact-sections{{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}}.section-chip{{border:1px solid #dbeafe;background:#eff6ff;color:#1d4ed8;border-radius:999px;padding:9px 13px;font-weight:900;cursor:pointer}}.section-chip.active{{background:#1d4ed8;color:#fff}}.section-detail{{margin-top:12px;border:1px solid #e6ebf3;border-radius:18px;background:#fff;padding:14px 16px}}.section-detail-head{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:8px}}.section-detail-head b{{color:#1d4ed8}}.copy-section{{border:1px solid #dbeafe;background:#fff;color:#1d4ed8;border-radius:999px;padding:7px 10px;font-weight:900;cursor:pointer}}.section-detail ul{{margin:8px 0 0;padding-left:20px}}.section-detail li{{margin:6px 0;line-height:1.65;color:#475569}}</style></head><body><div class='app'><header class='top'><div class='brand'><div class='icon'>🖼️</div><div>历史情景插图</div></div><div><a href='{PUBLIC_BASE}/index.html' target='_blank'>成果库</a> <button id='openCreateTop'>开始创作</button></div></header><main class='workspace'><section class='chat'><div class='chat-scroll' id='chatScroll'><div class='message'><div class='avatar'>🖼️</div><div class='bubble'><h2>你好，我是历史情景插图助手</h2><p>这里保存的是本次历史情景插图成果，可继续查看方案、下载示意图，或基于当前主题重新创作。</p></div></div><div class='message user'><div class='bubble'><p>{safe_input}</p></div></div><div class='message'><div class='avatar'>🖼️</div><div class='bubble'><h2>已生成历史情景插图</h2><p class='result-note'>图片是核心产物。文字方案已收起为栏目按钮，需要时点击查看并可一键复制。</p>{visual_block}<div class='result-grid compact-sections' data-role='section-chips'>{compact_buttons}</div><div class='section-detail' data-role='section-detail' style='display:none'></div></div></div></div><div class='composer'><textarea id='quickInput' placeholder='请输入提问内容'></textarea><button class='send' id='sendBtn'>↑</button></div></section><aside class='side' style='display:none'><h3>插图预览</h3><div class='preview'>{f"<iframe src='{html.escape(svg_url)}' title='历史情景插图预览'></iframe>" if svg_url else '<div>暂无预览</div>'}</div><div class='tools'><button class='primary' id='openCreateSide'>新建创作</button><a class='ghost' href='{html.escape(svg_url)}' target='_blank' {'style="display:none"' if not svg_url else ''}>打开插图文件</a></div><div class='meta'>生成时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}<br>保存成果页保留聊天工作台形态。</div></aside></main></div><div class='modal-mask' id='modalMask'><div class='modal'><button class='close' id='closeModal'>×</button><h2>开始创作</h2><div class='desc'>请填写历史情景、风格、色调、尺寸和补充要求。</div><div class='field'><label><em>*</em>历史情景或古诗词</label><textarea>{scene_val}</textarea></div><div class='field'><label><em>*</em>风格</label><select><option>水粉画</option><option>国风写实插画</option><option>古画长卷风</option></select></div><div class='field'><label><em>*</em>选择色调</label><select><option>柔和色调</option><option>暖黄色调</option><option>青绿色调</option></select></div><div class='field'><label>尺寸</label><select><option>1024*1024（1:1）</option><option>1365*768（16:9）</option><option>768*1365（9:16）</option></select></div><div class='field'><label>其他要求</label><textarea placeholder='请提供任何其他你认为重要的信息或要求。'></textarea></div><button class='ai-btn'>⚡ 开始生成</button></div></div><script>function openLightbox(url){{let box=document.getElementById('imageLightbox');if(!box){{box=document.createElement('div');box.id='imageLightbox';box.className='lightbox';box.innerHTML='<button type=\"button\">关闭 ×</button><img alt=\"全屏查看历史情景插图\">';document.body.appendChild(box);box.querySelector('button').onclick=()=>box.classList.remove('show');box.onclick=e=>{{if(e.target===box)box.classList.remove('show')}}}}box.querySelector('img').src=url;box.classList.add('show')}}document.getElementById('openCreateTop').onclick=()=>document.getElementById('modalMask').classList.add('show');document.getElementById('openCreateSide').onclick=()=>document.getElementById('modalMask').classList.add('show');document.getElementById('closeModal').onclick=()=>document.getElementById('modalMask').classList.remove('show');
const SAVED_SECTIONS={compact_json};
function showSavedSection(idx){{const sec=SAVED_SECTIONS[idx];if(!sec)return;document.querySelectorAll('.section-chip').forEach((b,i)=>b.classList.toggle('active',i===idx));const box=document.querySelector('[data-role="section-detail"]');const items=Array.isArray(sec.items)?sec.items:[];box.style.display='block';box.innerHTML=`<div class="section-detail-head"><b>${{esc(sec.title||'栏目内容')}}</b><button class="copy-section" type="button" data-copy-sec="${{idx}}">一键复制</button></div><ul>${{items.length?items.map(x=>`<li>${{esc(x)}}</li>`).join(''):'<li>暂无内容。</li>'}}</ul>`;const btn=box.querySelector('[data-copy-sec]');if(btn)btn.onclick=()=>copySavedSection(idx);}}
function copySavedSection(idx){{const sec=SAVED_SECTIONS[idx];if(!sec)return;const text=[sec.title||'栏目内容',...((sec.items||[]).map(x=>'• '+x))].join('\n');navigator.clipboard?.writeText(text).then(()=>toast('已复制该栏目内容')).catch(()=>toast('复制失败，请手动选择文本'));}}
document.querySelectorAll('.section-chip').forEach((btn,idx)=>btn.onclick=()=>showSavedSection(idx));
</script></body></html>"""
    path=GENERATED_DIR/f"{aid}.html"
